package com.fourtwentykc;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.MultipleGradientPaint;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.function.LongSupplier;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Smoke and confetti over the whole game screen. Each piece lives in fractions of the screen, so a resize mid-blaze
 * keeps it where it was, and each effect fades in and out over its own duration.
 */
class BlazeOverlay extends Overlay
{
	static final int SMOKE_PUFFS = 56;
	static final int MOST_CONFETTI = 320;
	// The kc greens, from lime to leaf.
	static final Color[] GREENS = {
		new Color(0x4E, 0xF0, 0x15), new Color(0xCA, 0xFF, 0x00), new Color(0x2E, 0xB8, 0x2E),
		new Color(0x7C, 0xFC, 0x00), new Color(0x1F, 0x8A, 0x1F),
	};
	// Smoke is soft, so it draws at a quarter of the screen's width and height and is scaled up once: a sixteenth of
	// the blending, the same look.
	static final int SMOKE_SCALE = 4;
	static final float SMOKE_PACE = 3;
	// Smoke drifts slowly, so its layer is redrawn twenty times a second and shown as it is between.
	static final long SMOKE_REDRAW_NANOS = 50_000_000L;
	private static final BufferedImage PUFF = puff(128);

	private final Client client;
	private final LongSupplier nanos;
	private final Random random = new Random();
	private final List<Puff> puffs = new ArrayList<>();
	private final List<Flake> flakes = new ArrayList<>();
	private Effect smoke;
	private Effect confetti;
	private BufferedImage smokeLayer;
	private long smokeLayerAt;

	BlazeOverlay(Client client)
	{
		this(client, System::nanoTime);
	}

	BlazeOverlay(Client client, LongSupplier nanos)
	{
		this.client = client;
		this.nanos = nanos;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	/** One effect's run: when it began, how long it lasts and how strong it is at its peak (0 to 1). */
	static final class Effect
	{
		final long start;
		final long length;
		final float strength;

		Effect(long start, long length, float strength)
		{
			this.start = start;
			this.length = length;
			this.strength = strength;
		}

		/** Seconds since it began. */
		float age(long now)
		{
			return (now - start) / 1e9f;
		}

		boolean over(long now)
		{
			return now - start >= length;
		}

		/** Its strength now: up over the first second, down over the last third, never past its peak. */
		float level(long now)
		{
			float t = age(now);
			float total = length / 1e9f;
			float in = Math.min(1f, t / Math.min(1f, total / 4));
			float out = Math.min(1f, (total - t) / (total / 3));
			return strength * Math.max(0f, Math.min(in, out));
		}
	}

	/** A puff of smoke: where it starts and drifts, how big it grows, how much of the smoke it carries. */
	private static final class Puff
	{
		float x;
		float y;
		float dx;
		float dy;
		float size;
		float grow;
		float alpha;
	}

	/** A piece of confetti: when it drops, where, how it falls, sways and spins, and its green. */
	private static final class Flake
	{
		float delay;
		float x;
		float fall;
		float sway;
		float swaySpeed;
		float phase;
		float spin;
		float width;
		float height;
		Color color;
	}

	/** Smoke for this many seconds at this density (percent of full); smoke already rolling plays on. */
	void smoke(int seconds, int density)
	{
		if (running(smoke))
		{
			return;
		}
		puffs.clear();
		for (int i = 0; i < SMOKE_PUFFS; i++)
		{
			Puff puff = new Puff();
			puff.x = random.nextFloat();
			// Most of it rises from the lower half of the screen.
			puff.y = 0.35f + random.nextFloat() * 0.75f;
			puff.dx = (random.nextFloat() - 0.5f) * 0.03f;
			puff.dy = -(0.015f + random.nextFloat() * 0.035f);
			puff.size = 0.12f + random.nextFloat() * 0.22f;
			puff.grow = 0.03f + random.nextFloat() * 0.05f;
			puff.alpha = 0.3f + random.nextFloat() * 0.6f;
			puffs.add(puff);
		}
		smoke = new Effect(nanos.getAsLong(), seconds * 1_000_000_000L, density / 100f);
	}

	/** Confetti for this many seconds, at this density (percent of the most there can be); confetti falling plays on. */
	void confetti(int seconds, int density)
	{
		if (running(confetti))
		{
			return;
		}
		flakes.clear();
		int count = Math.max(1, MOST_CONFETTI * density / 100);
		for (int i = 0; i < count; i++)
		{
			Flake flake = new Flake();
			// Drops come through the first two thirds of the run, so it rains the whole time.
			flake.delay = random.nextFloat() * seconds * 2 / 3;
			flake.x = random.nextFloat();
			flake.fall = 0.18f + random.nextFloat() * 0.22f;
			flake.sway = 0.004f + random.nextFloat() * 0.012f;
			flake.swaySpeed = 1.5f + random.nextFloat() * 2.5f;
			flake.phase = random.nextFloat() * 6.283f;
			flake.spin = (random.nextFloat() - 0.5f) * 10f;
			flake.width = 4 + random.nextFloat() * 4;
			flake.height = 7 + random.nextFloat() * 6;
			flake.color = GREENS[random.nextInt(GREENS.length)];
			flakes.add(flake);
		}
		confetti = new Effect(nanos.getAsLong(), seconds * 1_000_000_000L, 1f);
	}

	/** Everything stops at once. */
	void stop()
	{
		smoke = null;
		confetti = null;
		puffs.clear();
		flakes.clear();
		smokeLayer = null;
	}

	private boolean running(Effect effect)
	{
		return effect != null && !effect.over(nanos.getAsLong());
	}

	boolean active()
	{
		return running(smoke) || running(confetti);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long now = nanos.getAsLong();
		if (smoke != null && smoke.over(now))
		{
			smoke = null;
		}
		if (confetti != null && confetti.over(now))
		{
			confetti = null;
		}
		if (!active())
		{
			return null;
		}
		int w = client.getCanvasWidth();
		int h = client.getCanvasHeight();
		Composite composite = g.getComposite();
		AffineTransform transform = g.getTransform();
		RenderingHints hints = g.getRenderingHints();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		if (smoke != null)
		{
			paintSmoke(g, w, h, now);
		}
		else
		{
			smokeLayer = null;
		}
		if (confetti != null)
		{
			paintConfetti(g, w, h, now);
		}
		g.setComposite(composite);
		g.setTransform(transform);
		g.setRenderingHints(hints);
		return null;
	}

	private void paintSmoke(Graphics2D g, int w, int h, long now)
	{
		float level = smoke.level(now);
		if (level <= 0)
		{
			return;
		}
		int lw = Math.max(1, w / SMOKE_SCALE);
		int lh = Math.max(1, h / SMOKE_SCALE);
		boolean resized = smokeLayer == null || smokeLayer.getWidth() != lw || smokeLayer.getHeight() != lh;
		if (resized)
		{
			smokeLayer = new BufferedImage(lw, lh, BufferedImage.TYPE_INT_ARGB_PRE);
		}
		if (resized || now - smokeLayerAt >= SMOKE_REDRAW_NANOS)
		{
			smokeLayerAt = now;
			drawSmokeLayer(lw, lh, level, now);
		}
		// Smoke changes so gently from pixel to pixel that the plain upscale looks the same as a smooth one, at a
		// fraction of the cost.
		g.setComposite(AlphaComposite.SrcOver);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		g.drawImage(smokeLayer, 0, 0, w, h, null);
	}

	/** The puffs into the quarter-size layer, as they stand now. */
	private void drawSmokeLayer(int lw, int lh, float level, long now)
	{
		Graphics2D layer = smokeLayer.createGraphics();
		layer.setComposite(AlphaComposite.Clear);
		layer.fillRect(0, 0, lw, lh);
		layer.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		// The smoke moves through its run at the pace of a three-second one, so a long run rolls slowly instead of
		// swelling past the screen.
		float t = smoke.age(now) * SMOKE_PACE / (smoke.length / 1e9f);
		int span = Math.max(lw, lh);
		for (Puff puff : puffs)
		{
			int size = (int) (span * (puff.size + puff.grow * t));
			int x = (int) (lw * (puff.x + puff.dx * t)) - size / 2;
			int y = (int) (lh * (puff.y + puff.dy * t)) - size / 2;
			layer.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(1f, level * puff.alpha)));
			layer.drawImage(PUFF, x, y, size, size, null);
		}
		layer.dispose();
	}

	private void paintConfetti(Graphics2D g, int w, int h, long now)
	{
		float level = confetti.level(now);
		float t = confetti.age(now);
		AffineTransform base = g.getTransform();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0f, Math.min(1f, level))));
		for (Flake flake : flakes)
		{
			float fell = t - flake.delay;
			if (fell < 0)
			{
				continue;
			}
			float y = -0.05f + flake.fall * fell;
			if (y > 1.05f)
			{
				continue;
			}
			float x = flake.x + flake.sway * (float) Math.sin(flake.phase + flake.swaySpeed * fell) * 8;
			g.setTransform(base);
			g.translate(x * w, y * h);
			g.rotate(flake.phase + flake.spin * fell);
			// A flat piece turning in the air: its width swings through its edge.
			g.scale(Math.cos(flake.phase + fell * flake.swaySpeed * 1.7), 1);
			g.setColor(flake.color);
			g.fillRect((int) (-flake.width / 2), (int) (-flake.height / 2), (int) flake.width, (int) flake.height);
		}
		g.setTransform(base);
	}

	/** One soft puff: a pale, faintly green cloud that fades to nothing at its edge. */
	static BufferedImage puff(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		float r = size / 2f;
		g.setPaint(new RadialGradientPaint(r, r, r, new float[]{0f, 0.45f, 1f},
			new Color[]{new Color(225, 235, 225, 200), new Color(205, 220, 205, 110), new Color(190, 205, 190, 0)},
			MultipleGradientPaint.CycleMethod.NO_CYCLE));
		g.fillOval(0, 0, size, size);
		g.dispose();
		return image;
	}
}

package com.fourtwentykc;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WidgetNode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;

/**
 * The 420 in the game's own popup, the one a new collection log slot raises. It waits its turn behind the game's
 * own popups (collection log slots, combat achievement tasks), one at a time. Everything here runs on the client
 * thread, a game tick at a time.
 */
final class BlazePopup
{
	static final String TITLE = "420";
	static final String BODY = "Blaze it!";
	// The game's notification_display_init: title, body, title colour.
	private static final int NOTIFICATION_DISPLAY_INIT = 3343;
	private static final int TITLE_COLOUR = 0x00ff00;
	// The game queues its own popups back to back: the slot must stand empty this many ticks before ours shows, so it
	// comes after the whole series and never between two of them.
	static final int QUIET_TICKS = 3;

	// Each window layout keeps its own place for the game's notifications; any other layout shows none.
	private static final int[][] SLOTS = {
		{InterfaceID.TOPLEVEL, InterfaceID.Toplevel.NOTIFICATIONS},
		{InterfaceID.TOPLEVEL_PRE_EOC, InterfaceID.ToplevelPreEoc.NOTIFICATIONS},
		{InterfaceID.TOPLEVEL_OSRS_STRETCH, InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS},
	};

	private final Client client;
	private int waiting;
	private int quiet;
	private WidgetNode showing;

	BlazePopup(Client client)
	{
		this.client = client;
	}

	/** Queues a popup, shown once the game's own have played. */
	void show()
	{
		waiting++;
	}

	/** Each game tick: a popup that has played closes, and the next one shows when the slot has been quiet. */
	void tick()
	{
		GameState state = client.getGameState();
		if (state == GameState.LOADING)
		{
			// A region loading mid-session keeps the game's interfaces: everything waits for it.
			return;
		}
		if (state != GameState.LOGGED_IN)
		{
			// Game ticks stop with a logout or hop; any other state leaves our popup to the game.
			showing = null;
			quiet = 0;
			return;
		}
		if (showing != null)
		{
			if (slotOf(showing) >= 0 && playing())
			{
				return;
			}
			close();
			return;
		}
		int slot = notificationSlot();
		if (waiting == 0 || slot < 0 || client.getWidget(slot) == null
			|| client.getComponentTable().get(slot) != null && playing())
		{
			quiet = 0;
			return;
		}
		if (++quiet < QUIET_TICKS)
		{
			return;
		}
		quiet = 0;
		showing = client.openInterface(slot, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
		// Taken from the queue only once it is open.
		waiting--;
		client.runScript(NOTIFICATION_DISPLAY_INIT, TITLE, "<col=ffffff>" + BODY + "</col>", TITLE_COLOUR);
	}

	/** Everything goes with the plugin: the queue, and our popup if it is still up. */
	void clear()
	{
		waiting = 0;
		quiet = 0;
		close();
	}

	/** A popup is on screen: the game shrinks its container to nothing once it has played. */
	private boolean playing()
	{
		Widget container = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
		return container != null && container.getWidth() > 0;
	}

	/** The notification slot holding this popup, in whichever layout it now sits (a layout change moves it); or -1. */
	private int slotOf(WidgetNode node)
	{
		for (int[] layout : SLOTS)
		{
			if (client.getComponentTable().get(layout[1]) == node)
			{
				return layout[1];
			}
		}
		return -1;
	}

	/** Our popup closes where it sits; one the game has already taken away is only forgotten. */
	private void close()
	{
		if (showing != null && slotOf(showing) >= 0)
		{
			client.closeInterface(showing, true);
		}
		showing = null;
	}

	/** This layout's notification slot, or -1 for a layout that shows none. */
	private int notificationSlot()
	{
		int toplevel = client.getTopLevelInterfaceId();
		for (int[] layout : SLOTS)
		{
			if (layout[0] == toplevel)
			{
				return layout[1];
			}
		}
		return -1;
	}
}

package com.fourtwentykc;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("fourtwentykc")
public interface FourTwentyKcConfig extends Config
{
	@ConfigSection(
		name = "Smoke",
		description = "Smoke rolls over the game screen",
		position = 2
	)
	String smokeSection = "smoke";

	@ConfigSection(
		name = "Confetti",
		description = "Green confetti falls over the game screen",
		position = 3
	)
	String confettiSection = "confetti";

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat messages",
		description = "Show a message in chat when a tracked count reaches 420",
		position = 0
	)
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "popup",
		name = "Popup",
		description = "Show the game's collection log popup when a tracked count reaches 420",
		position = 1
	)
	default boolean popup()
	{
		return true;
	}

	@ConfigItem(
		keyName = "smoke",
		name = "Smoke",
		description = "Roll smoke over the game screen when a tracked count reaches 420. Test in chat with ::420",
		section = smokeSection,
		position = 0
	)
	default boolean smoke()
	{
		return true;
	}

	@Range(min = 1, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "smokeDensity",
		name = "Density",
		description = "How thick the smoke is",
		section = smokeSection,
		position = 1
	)
	default int smokeDensity()
	{
		return 50;
	}

	@Range(min = 1, max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "smokeDuration",
		name = "Duration",
		description = "How long the smoke lasts",
		section = smokeSection,
		position = 2
	)
	default int smokeDuration()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "confetti",
		name = "Confetti",
		description = "Drop green confetti over the game screen when a tracked count reaches 420. Test in chat with ::420",
		section = confettiSection,
		position = 0
	)
	default boolean confetti()
	{
		return true;
	}

	@Range(min = 1, max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "confettiDensity",
		name = "Density",
		description = "How much confetti falls",
		section = confettiSection,
		position = 1
	)
	default int confettiDensity()
	{
		return 50;
	}

	@Range(min = 1, max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "confettiDuration",
		name = "Duration",
		description = "How long the confetti falls",
		section = confettiSection,
		position = 2
	)
	default int confettiDuration()
	{
		return 3;
	}
}

package com.fourtwentykc;

import com.google.inject.Provides;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "420 kc",
	description = "Celebrate when boss, activity, or clue counts reach 420",
	tags = {"420", "kc", "boss", "kill count", "activity", "clue", "clue scroll", "popup", "smoke", "confetti"}
)
public class FourTwentyKcPlugin extends Plugin
{
	// Mirrors RuneLite's ChatCommandsPlugin KILLCOUNT_PATTERN: the game says
	// "kill count" for bosses but "completion count" for the Gauntlet, "completed"
	// for raids, "subdued" for Wintertodt, plus harvest/lap/success variants.
	// Matching only "kill count" missed a 420 Gauntlet completion (2026-07-28).
	// The number keeps its <col> wrapper as the discriminator, so this stays as
	// strict as RuneLite's own parser.
	static final Pattern KC_PATTERN = Pattern.compile(
		"Your (?:completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?.+?(?:</col>)? "
			+ "(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?"
			+ "is: ?<col=[0-9a-f]{6}>([0-9,]+)</col>");

	// The count-bearing messages that do NOT say "count is:" at all, from the
	// same ChatCommandsPlugin catalog (2026-07-30 audit - the full sweep after
	// the Gauntlet taught us Jagex never uses one wording when five will do).
	// One capturing group each: the count.
	static final Pattern SEPULCHRE_PATTERN = Pattern.compile(
		"You have completed Floor \\d of the Hallowed Sepulchre! Total completions: "
			+ "<col=ff0000>([0-9,]+)</col>\\.");
	static final Pattern GRAND_HALLOWED_COFFIN_PATTERN = Pattern.compile(
		"You have opened the Grand Hallowed Coffin <col=ff0000>([0-9,]+)</col> times?!");
	static final Pattern RIFTS_CLOSED_PATTERN = Pattern.compile(
		"Amount of Rifts you have closed: <col=ff0000>([0-9,]+)</col>\\.",
		Pattern.CASE_INSENSITIVE);
	static final Pattern HUNTER_RUMOUR_PATTERN = Pattern.compile(
		"You have completed <col=[0-9a-f]{6}>([0-9,]+)</col> rumours? for the Hunter Guild\\.");
	static final Pattern BIRD_EGG_PATTERN = Pattern.compile(
		"You have made <col=ff0000>([0-9,]+)</col> offerings?\\.");
	static final Pattern CHEST_OPENING_PATTERN = Pattern.compile(
		"You have opened (?:the )?(?:crystal chest|Larran's big chest|Larran's small chest"
			+ "|Brimstone chest) ([0-9,]+) times\\.");

	// RuneLite parses clue totals separately in LootTrackerPlugin. The count has
	// no dedicated col wrapper and precedes the tier; the optional plural matches
	// both first and later completions.
	static final Pattern TREASURE_TRAIL_PATTERN = Pattern.compile(
		"You have completed ([0-9,]+) [a-z]+ Treasure Trails?\\.");

	// Duel Arena wins/losses are in RuneLite's catalog but the content left the
	// game; those messages can no longer occur, so they are deliberately absent.
	static final Pattern[] KC_PATTERNS = {
		KC_PATTERN, SEPULCHRE_PATTERN, GRAND_HALLOWED_COFFIN_PATTERN,
		RIFTS_CLOSED_PATTERN, HUNTER_RUMOUR_PATTERN, BIRD_EGG_PATTERN,
		CHEST_OPENING_PATTERN, TREASURE_TRAIL_PATTERN,
	};

	/** The count carried by a game message, or null if it carries none. */
	static String countFrom(String message)
	{
		for (Pattern pattern : KC_PATTERNS)
		{
			Matcher matcher = pattern.matcher(message);
			if (matcher.find())
			{
				return matcher.group(1);
			}
		}
		return null;
	}

	@Inject
	private FourTwentyKcConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	// Each start of the plugin draws with its own overlay and popup, so an earlier stop's cleanup can never end a
	// celebration that began after it.
	private BlazeOverlay overlay;
	private BlazePopup popup;

	@Provides
	FourTwentyKcConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FourTwentyKcConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlay = new BlazeOverlay(client);
		popup = new BlazePopup(client);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		// The overlay draws and the popup lives on the client thread: they end there too.
		BlazeOverlay stopping = overlay;
		BlazePopup closing = popup;
		clientThread.invoke(() ->
		{
			stopping.stop();
			closing.clear();
		});
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		popup.tick();
	}

	/** {@code ::420} shows the celebration as it is set, without waiting for a real 420. */
	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if ("420".equals(event.getCommand()))
		{
			celebrate();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		// Match the raw message: the <col> tags around the number are part of
		// the patterns' strictness, so they must survive to the matcher.
		String count = countFrom(event.getMessage());
		if (count == null)
		{
			return;
		}

		String kcStr = count.replace(",", "");
		int kc;
		try
		{
			kc = Integer.parseInt(kcStr);
		}
		catch (NumberFormatException e)
		{
			return;
		}

		if (kc != 420)
		{
			return;
		}
		if (config.chatMessages())
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.GAMEMESSAGE)
				.runeLiteFormattedMessage("<col=00ff00>420 kc</col>: blaze it!")
				.build());
		}
		celebrate();
	}

	/** The popup, smoke and confetti, each as its setting says. */
	private void celebrate()
	{
		if (config.popup())
		{
			popup.show();
		}
		if (config.smoke())
		{
			overlay.smoke(config.smokeDuration(), config.smokeDensity());
		}
		if (config.confetti())
		{
			overlay.confetti(config.confettiDuration(), config.confettiDensity());
		}
	}
}

package com.fourtwentykc;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HashTable;
import net.runelite.api.WidgetNode;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** The 420 popup waits its turn behind the game's own and never strands, blocks or closes what is not its own. */
public class BlazePopupTest
{
	private static final int SLOT = InterfaceID.Toplevel.NOTIFICATIONS;

	private static final int STRETCH_SLOT = InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS;

	private GameState state = GameState.LOGGED_IN;
	private int toplevel = InterfaceID.TOPLEVEL;
	private boolean openFails;
	private boolean slotBuilt = true;
	private int containerWidth;
	private final Map<Long, WidgetNode> table = new HashMap<>();
	private final List<WidgetNode> opened = new ArrayList<>();
	private final List<WidgetNode> closed = new ArrayList<>();
	private BlazePopup popup;

	@Before
	public void setUp()
	{
		popup = new BlazePopup(client());
	}

	@Test
	public void itWaitsForTheSlotToStandQuiet()
	{
		popup.show();
		for (int i = 1; i < BlazePopup.QUIET_TICKS; i++)
		{
			popup.tick();
			assertEquals(0, opened.size());
		}
		popup.tick();
		assertEquals(1, opened.size());
	}

	@Test
	public void itComesAfterTheGamesOwnSeries()
	{
		popup.show();
		WidgetNode game = gamePopup();
		for (int i = 0; i < 10; i++)
		{
			popup.tick();
		}
		assertEquals("never over a game popup that is playing", 0, opened.size());
		// One ends and the next of the game's own follows a tick later: ours waits through the gap.
		containerWidth = 0;
		popup.tick();
		containerWidth = 200;
		table.put((long) SLOT, gamePopup());
		popup.tick();
		popup.tick();
		assertEquals(0, opened.size());
		containerWidth = 0;
		for (int i = 0; i < BlazePopup.QUIET_TICKS; i++)
		{
			popup.tick();
		}
		assertEquals(1, opened.size());
		assertTrue(game != opened.get(0));
	}

	@Test
	public void aPlayedPopupClosesAndTheNextShows()
	{
		popup.show();
		popup.show();
		quietTicks();
		assertEquals(1, opened.size());
		containerWidth = 200;
		popup.tick();
		assertEquals(0, closed.size());
		containerWidth = 0;
		popup.tick();
		assertEquals(1, closed.size());
		quietTicks();
		assertEquals(2, opened.size());
	}

	@Test
	public void aHopNeverBlocksOrStrandsTheQueue()
	{
		popup.show();
		popup.show();
		quietTicks();
		containerWidth = 200;
		// The hop takes the game's interfaces: our popup is gone without a close.
		state = GameState.HOPPING;
		table.clear();
		popup.tick();
		state = GameState.LOGGED_IN;
		containerWidth = 0;
		quietTicks();
		assertEquals("the queued one shows after the hop", 2, opened.size());
		assertEquals("nothing closed that was no longer there", 0, closed.size());
	}

	@Test
	public void aPopupWaitsForTheSlotAfterLogin()
	{
		slotBuilt = false;
		popup.show();
		for (int i = 0; i < 10; i++)
		{
			popup.tick();
		}
		assertEquals(0, opened.size());
		slotBuilt = true;
		quietTicks();
		assertEquals(1, opened.size());
	}

	@Test
	public void aLayoutChangeKeepsOurPopupOurs()
	{
		popup.show();
		quietTicks();
		WidgetNode ours = opened.get(0);
		containerWidth = 200;
		// Fixed to resizable: the game moves the playing popup into the new layout's slot.
		table.clear();
		table.put((long) STRETCH_SLOT, ours);
		toplevel = InterfaceID.TOPLEVEL_OSRS_STRETCH;
		popup.tick();
		assertEquals("still playing, still ours", 0, closed.size());
		containerWidth = 0;
		popup.tick();
		assertEquals("closed where it now sits", 1, closed.size());
		assertTrue(closed.get(0) == ours);
		popup.show();
		quietTicks();
		assertEquals(2, opened.size());
		containerWidth = 200;
		popup.clear();
		assertEquals("and the plugin's end closes it too", 2, closed.size());
	}

	@Test
	public void aLayoutWithNoNotificationsWaitsWithoutLosingTheQueue()
	{
		toplevel = InterfaceID.TOPLEVEL_DISPLAY;
		popup.show();
		for (int i = 0; i < 10; i++)
		{
			popup.tick();
		}
		assertEquals(0, opened.size());
		toplevel = InterfaceID.TOPLEVEL;
		quietTicks();
		assertEquals(1, opened.size());
	}

	@Test
	public void aFailedOpenKeepsTheCelebrationQueued()
	{
		popup.show();
		openFails = true;
		try
		{
			quietTicks();
		}
		catch (IllegalStateException expected)
		{
			// The event bus logs it; the queue keeps the popup.
		}
		openFails = false;
		quietTicks();
		assertEquals(1, opened.size());
	}

	@Test
	public void clearingClosesOnlyItsOwn()
	{
		popup.show();
		quietTicks();
		containerWidth = 200;
		// A layout change moved the slot's contents on: the node is no longer ours to close.
		table.put((long) SLOT, gamePopup());
		popup.clear();
		assertEquals(0, closed.size());
		popup.show();
		popup.clear();
		table.clear();
		containerWidth = 0;
		quietTicks();
		assertEquals("cleared means nothing waits", 1, opened.size());
	}

	private void quietTicks()
	{
		for (int i = 0; i < BlazePopup.QUIET_TICKS; i++)
		{
			popup.tick();
		}
	}

	private WidgetNode gamePopup()
	{
		WidgetNode node = node();
		table.put((long) SLOT, node);
		containerWidth = 200;
		return node;
	}

	private static WidgetNode node()
	{
		return (WidgetNode) Proxy.newProxyInstance(BlazePopupTest.class.getClassLoader(), new Class<?>[]{WidgetNode.class},
			(proxy, method, args) -> method.getName().equals("equals") ? proxy == args[0]
				: method.getName().equals("hashCode") ? System.identityHashCode(proxy) : null);
	}

	@SuppressWarnings("unchecked")
	private Client client()
	{
		HashTable<WidgetNode> components = (HashTable<WidgetNode>) Proxy.newProxyInstance(getClass().getClassLoader(),
			new Class<?>[]{HashTable.class}, (proxy, method, args) -> table.get((Long) args[0]));
		Widget slot = (Widget) Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Widget.class},
			(proxy, method, args) -> null);
		Widget container = (Widget) Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Widget.class},
			(proxy, method, args) -> method.getName().equals("getWidth") ? containerWidth : null);
		return (Client) Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return state;
					case "getTopLevelInterfaceId":
						return toplevel;
					case "getComponentTable":
						return components;
					case "getWidget":
						int id = (Integer) args[0];
						return id == SLOT || id == STRETCH_SLOT ? (slotBuilt ? slot : null)
							: id == InterfaceID.NotificationDisplay.CONTAINER && !table.isEmpty() ? container : null;
					case "openInterface":
						if (openFails)
						{
							throw new IllegalStateException("component does not exist");
						}
						WidgetNode mine = node();
						table.put((long) (Integer) args[0], mine);
						opened.add(mine);
						containerWidth = 0;
						return mine;
					case "closeInterface":
						// The real client refuses a node no longer in the component table.
						if (!table.containsValue(args[0]))
						{
							throw new IllegalArgumentException("WidgetNode is no longer valid");
						}
						closed.add((WidgetNode) args[0]);
						table.values().remove(args[0]);
						return null;
					case "runScript":
						return null;
					default:
						throw new UnsupportedOperationException(method.getName());
				}
			});
	}
}

package com.fourtwentykc;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Proxy;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Client;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The smoke and confetti over their runs. */
public class BlazeTest
{
	private static final long SECOND = 1_000_000_000L;

	@Test
	public void anEffectRisesHoldsAndFallsWithinItsRun()
	{
		BlazeOverlay.Effect effect = new BlazeOverlay.Effect(0, 8 * SECOND, 0.6f);
		assertEquals(0, effect.level(0), 1e-6);
		assertEquals(0.3f, effect.level(SECOND / 2), 1e-4);
		assertEquals(0.6f, effect.level(3 * SECOND), 1e-4);
		assertTrue(effect.level(7 * SECOND) < 0.6f);
		assertEquals(0, effect.level(8 * SECOND), 1e-6);
		assertTrue(effect.over(8 * SECOND));
		assertFalse(effect.over(8 * SECOND - 1));
	}

	@Test
	public void smokeCoversTheScreenThenGoes()
	{
		AtomicLong clock = new AtomicLong();
		BlazeOverlay overlay = new BlazeOverlay(canvas(400, 300), clock::get);
		overlay.smoke(4, 80);
		clock.set(2 * SECOND);
		BufferedImage mid = paint(overlay, 400, 300);
		assertTrue("smoke lies over much of the screen", covered(mid) > 0.4);
		clock.set(4 * SECOND);
		assertEquals(0, covered(paint(overlay, 400, 300)), 0);
		assertFalse(overlay.active());
	}

	@Test
	public void thickerSmokeIsThicker()
	{
		AtomicLong clock = new AtomicLong();
		BlazeOverlay thin = new BlazeOverlay(canvas(200, 200), clock::get);
		BlazeOverlay thick = new BlazeOverlay(canvas(200, 200), clock::get);
		thin.smoke(6, 20);
		thick.smoke(6, 100);
		clock.set(3 * SECOND);
		assertTrue(opacity(paint(thick, 200, 200)) > 2 * opacity(paint(thin, 200, 200)));
	}

	@Test
	public void confettiFallsInGreenAndMoreWithDensity()
	{
		AtomicLong clock = new AtomicLong();
		BlazeOverlay little = new BlazeOverlay(canvas(400, 300), clock::get);
		BlazeOverlay lots = new BlazeOverlay(canvas(400, 300), clock::get);
		little.confetti(6, 10);
		lots.confetti(6, 100);
		clock.set(3 * SECOND);
		BufferedImage few = paint(little, 400, 300);
		BufferedImage many = paint(lots, 400, 300);
		assertTrue(covered(many) > 3 * covered(few));
		for (int y = 0; y < many.getHeight(); y++)
		{
			for (int x = 0; x < many.getWidth(); x++)
			{
				int argb = many.getRGB(x, y);
				if ((argb >>> 24) > 0)
				{
					int r = (argb >> 16) & 0xff;
					int g = (argb >> 8) & 0xff;
					int b = argb & 0xff;
					assertTrue("every piece is green", g >= r && g > b);
				}
			}
		}
		clock.set(6 * SECOND);
		assertEquals(0, covered(paint(lots, 400, 300)), 0);
	}

	@Test
	public void aSecondCelebrationLetsTheFirstPlayOn()
	{
		AtomicLong clock = new AtomicLong();
		BlazeOverlay overlay = new BlazeOverlay(canvas(200, 200), clock::get);
		overlay.smoke(3, 100);
		overlay.confetti(3, 100);
		clock.set(3 * SECOND / 2);
		double before = opacity(paint(overlay, 200, 200));
		overlay.smoke(3, 100);
		overlay.confetti(3, 100);
		assertEquals("no snap back to nothing", before, opacity(paint(overlay, 200, 200)), 1e-9);
		clock.set(3 * SECOND);
		assertFalse("and it ends when the first does", overlay.active());
	}

	@Test
	public void anEarlierStopNeverEndsALaterCelebration()
	{
		// Each start of the plugin draws with its own overlay, so the last stop's cleanup can only reach its own.
		AtomicLong clock = new AtomicLong();
		BlazeOverlay before = new BlazeOverlay(canvas(100, 100), clock::get);
		BlazeOverlay after = new BlazeOverlay(canvas(100, 100), clock::get);
		after.confetti(3, 50);
		before.stop();
		assertTrue(after.active());
	}

	@Test
	public void smokeKeepsRollingBetweenRedraws()
	{
		// Redrawn twenty times a second: frames in one twentieth match, frames further apart move on.
		AtomicLong clock = new AtomicLong();
		BlazeOverlay overlay = new BlazeOverlay(canvas(200, 200), clock::get);
		overlay.smoke(3, 100);
		clock.set(SECOND);
		BufferedImage first = paint(overlay, 200, 200);
		clock.addAndGet(BlazeOverlay.SMOKE_REDRAW_NANOS / 2);
		assertTrue("the layer is reused inside its twentieth", same(first, paint(overlay, 200, 200)));
		clock.addAndGet(BlazeOverlay.SMOKE_REDRAW_NANOS * 6);
		assertFalse("and rolls on past it", same(first, paint(overlay, 200, 200)));
	}

	@Test
	public void stopClearsEverything()
	{
		AtomicLong clock = new AtomicLong();
		BlazeOverlay overlay = new BlazeOverlay(canvas(100, 100), clock::get);
		overlay.smoke(10, 50);
		overlay.confetti(10, 50);
		overlay.stop();
		clock.set(2 * SECOND);
		assertFalse(overlay.active());
		assertEquals(0, covered(paint(overlay, 100, 100)), 0);
	}

	private static Client canvas(int width, int height)
	{
		return (Client) Proxy.newProxyInstance(BlazeTest.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getCanvasWidth":
						return width;
					case "getCanvasHeight":
						return height;
					default:
						throw new UnsupportedOperationException(method.getName());
				}
			});
	}

	private static BufferedImage paint(BlazeOverlay overlay, int width, int height)
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		overlay.render(g);
		g.dispose();
		return image;
	}

	/** The share of pixels anything was painted on. */
	private static double covered(BufferedImage image)
	{
		int painted = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) > 0)
				{
					painted++;
				}
			}
		}
		return painted / (double) (image.getWidth() * image.getHeight());
	}

	private static boolean same(BufferedImage a, BufferedImage b)
	{
		for (int y = 0; y < a.getHeight(); y++)
		{
			for (int x = 0; x < a.getWidth(); x++)
			{
				if (a.getRGB(x, y) != b.getRGB(x, y))
				{
					return false;
				}
			}
		}
		return true;
	}

	/** The mean alpha across the image, 0 to 1. */
	private static double opacity(BufferedImage image)
	{
		long sum = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				sum += image.getRGB(x, y) >>> 24;
			}
		}
		return sum / (255.0 * image.getWidth() * image.getHeight());
	}
}

